calls.content:
{
  "summary": "Improve the safety and reliability of the existing URL-shortening service while preserving its documented API and existing analytics capabilities.",
  "changeType": "brownfield",
  "userStories": [
    {
      "id": "US1",
      "asA": "user",
      "iWant": "to create a short link only for a safe, valid destination URL",
      "soThat": "the link cannot use unsafe schemes or malformed destination data",
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC3",
        "AC4"
      ]
    },
    {
      "id": "US2",
      "asA": "user",
      "iWant": "the service to create a unique short code reliably",
      "soThat": "different links do not unexpectedly redirect to the wrong destination",
      "acceptanceCriteria": [
        "AC5",
        "AC6",
        "AC7"
      ]
    },
    {
      "id": "US3",
      "asA": "user",
      "iWant": "a short link to redirect predictably or return a clear error",
      "soThat": "I can distinguish a working link from a missing or invalid one",
      "acceptanceCriteria": [
        "AC8",
        "AC9",
        "AC10"
      ]
    },
    {
      "id": "US4",
      "asA": "user",
      "iWant": "link creation retries to be safe",
      "soThat": "a transient client or network retry does not unintentionally create multiple links",
      "acceptanceCriteria": [
        "AC11",
        "AC12"
      ]
    },
    {
      "id": "US5",
      "asA": "link owner",
      "iWant": "redirect analytics and audit information to remain accurate",
      "soThat": "I can understand link usage and operators can investigate failures",
      "acceptanceCriteria": [
        "AC13",
        "AC14"
      ]
    },
    {
      "id": "US6",
      "asA": "operator",
      "iWant": "security-relevant outcomes and unexpected failures to be logged safely",
      "soThat": "the service can be monitored without exposing sensitive URL data",
      "acceptanceCriteria": [
        "AC15",
        "AC16"
      ]
    }
  ],
  "functional": [
    "The existing link-creation endpoint shall validate the destination URL before persisting a link.",
    "Only http and https destination schemes shall be accepted by default. Schemes such as javascript, data, file, ftp, and custom schemes shall be rejected.",
    "Destination URLs containing control characters, malformed syntax, or embedded user information containing a username or password shall be rejected.",
    "The default safety policy shall reject localhost, loopback, link-local, and private-network IP literals and equivalent reserved hostnames as destinations. The service shall not perform outbound requests merely to validate a destination.",
    "A successful link creation shall persist the validated destination and its generated short code atomically.",
    "Short codes shall be protected by a database uniqueness constraint. A generated collision shall be retried within a bounded limit rather than overwriting an existing link.",
    "If bounded short-code generation retries are exhausted, the API shall return a structured server error and shall not persist a partial link.",
    "The redirect endpoint shall return a redirect response with the stored destination in the Location header for an existing short code.",
    "The redirect endpoint shall return the existing structured not-found error contract for an unknown short code and shall not redirect to a fallback destination.",
    "Validation and other client errors shall return the existing structured error response contract with an appropriate 4xx status.",
    "The link-creation endpoint shall accept an optional Idempotency-Key request header. For the same authenticated or otherwise equivalent request context and key, repeated requests shall return the original creation result without creating another link.",
    "An idempotency key shall be bound to the relevant request payload. Reusing it with a different destination shall return a 409 conflict using the structured error contract.",
    "Redirect events shall continue to be recorded only for successful redirects, and existing analytics endpoints shall report the recorded redirect events without counting failed lookups as clicks.",
    "Creation, redirect, validation failure, collision-retry exhaustion, and unexpected persistence failures shall produce auditable outcomes consistent with the existing audit model.",
    "The service shall preserve the documented public endpoint paths, response fields, analytics behavior, and existing valid-link behavior unless changed by the requirements above."
  ],
  "nonFunctional": [
    "Security: User-controlled destinations shall never be interpreted as executable content by the shortener; only the allowlisted URL schemes shall be accepted.",
    "Security: URLs, headers, and exceptions written to logs shall be sanitized and shall not include passwords, authorization credentials, API keys, or complete sensitive query strings.",
    "Reliability: Link creation shall be transactionally consistent; a successful response shall correspond to a persisted usable link.",
    "Reliability: Short-code collision handling shall be bounded and shall not cause an unbounded request hang.",
    "Reliability: Idempotency records and link records shall use durable storage compatible with the existing application database.",
    "Compatibility: Existing clients using valid documented URLs and endpoints shall continue to work.",
    "Observability: Logs shall contain correlation information, operation outcome, short-code identifier where safe, and a categorized failure reason.",
    "Testability: Validation, collision handling, idempotency, redirect behavior, analytics counting, structured errors, and audit/logging outcomes shall be covered by automated tests."
  ],
  "outOfScope": [
    "Malware, phishing, reputation, or blocklist scanning of destination domains.",
    "Fetching, crawling, or health-checking destination URLs.",
    "Guaranteeing that a destination remains safe after link creation.",
    "User authentication, authorization, ownership management, or administrative link deletion unless already required by the documented API.",
    "Expiration dates, link revocation, password-protected links, or per-link access controls.",
    "Changing the short-code alphabet or URL-domain configuration except where required to enforce uniqueness and reliability.",
    "Changing analytics dimensions or introducing new tracking identifiers beyond the existing redirect event model."
  ],
  "openQuestions": [
    {
      "question": "Should plain HTTP destinations remain supported, or must all new destinations use HTTPS?",
      "assumption": "Both HTTP and HTTPS remain supported for backward compatibility; unsafe and non-web schemes are rejected.",
      "answer": ""
    },
    {
      "question": "What exact definition of a private or reserved destination should be enforced for hostnames that resolve to private addresses?",
      "assumption": "The initial implementation rejects localhost, loopback, link-local, private-network, multicast, and unspecified IP literals plus standard reserved hostnames, but does not perform DNS resolution or outbound validation.",
      "answer": ""
    },
    {
      "question": "Should idempotency be mandatory for all creation requests or only supported when the client supplies Idempotency-Key?",
      "assumption": "Idempotency is optional and applies only when the client supplies a non-empty Idempotency-Key; requests without the header retain current creation semantics.",
      "answer": ""
    },
    {
      "question": "What is the existing database and migration mechanism for adding durable idempotency records and uniqueness constraints?",
      "assumption": "The implementation shall use the repository's existing persistence and migration conventions and shall add the minimum schema changes needed.",
      "answer": ""
    },
    {
      "question": "What redirect status code is part of the current public contract?",
      "assumption": "The existing documented redirect status is preserved; if no status is documented, use 302 Found to avoid permanently caching a potentially changeable redirect.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "A link-creation request with a valid absolute http or https URL returns the existing successful creation response and persists one link record containing the destination and short code."
    },
    {
      "id": "AC2",
      "criterion": "A link-creation request using javascript:, data:, file:, ftp:, or any non-http(s) scheme returns a structured 4xx response, creates no link record, and records a categorized validation outcome."
    },
    {
      "id": "AC3",
      "criterion": "A link-creation request containing malformed URL syntax, control characters, or URL user information returns a structured 4xx response and creates no link record."
    },
    {
      "id": "AC4",
      "criterion": "A link-creation request targeting localhost, a loopback/link-local/private/reserved IP literal, or a configured equivalent reserved hostname returns a structured 4xx response and creates no link record."
    },
    {
      "id": "AC5",
      "criterion": "The database rejects duplicate short codes, and a code collision during creation causes the service to generate another code without changing or deleting the existing link."
    },
    {
      "id": "AC6",
      "criterion": "After the configured bounded number of code-generation attempts is exhausted, creation returns a structured 5xx response, creates no link record, and emits an auditable failure outcome."
    },
    {
      "id": "AC7",
      "criterion": "Two concurrent successful creations produce distinct short codes and two independently retrievable link records, subject to normal transaction completion."
    },
    {
      "id": "AC8",
      "criterion": "Requesting an existing short-code endpoint returns the configured redirect status and a Location header exactly matching the persisted validated destination."
    },
    {
      "id": "AC9",
      "criterion": "Requesting an unknown short code returns the documented structured not-found response, does not include a Location header, and does not create a redirect event."
    },
    {
      "id": "AC10",
      "criterion": "A malformed or otherwise invalid short-code request returns the documented structured 4xx response without exposing a stack trace, database details, or credentials."
    },
    {
      "id": "AC11",
      "criterion": "Repeating a successful creation request with the same non-empty Idempotency-Key and equivalent payload returns the original creation result and leaves exactly one corresponding link record."
    },
    {
      "id": "AC12",
      "criterion": "Reusing an Idempotency-Key with a different payload returns a structured 409 response and does not create a second link."
    },
    {
      "id": "AC13",
      "criterion": "A successful redirect creates exactly one redirect event for that request, and the existing analytics endpoint includes it in the appropriate totals and dimensions."
    },
    {
      "id": "AC14",
      "criterion": "A failed lookup, rejected destination, or failed redirect does not increment successful-click analytics, while the corresponding audit outcome remains queryable through the existing persistence or audit mechanism."
    },
    {
      "id": "AC15",
      "criterion": "Validation failures, unknown short codes, code-generation exhaustion, idempotency conflicts, and unexpected persistence failures are emitted with categorized log or audit events and correlation information."
    },
    {
      "id": "AC16",
      "criterion": "Captured logs and audit records contain no password, authorization credential, API key, or unsanitized sensitive query-string value from a user-supplied URL."
    }
  ],
  "decisions": [
    {
      "title": "Classify the change as brownfield",
      "rationale": "The repository contains implemented controllers, services, repositories, domain objects, documentation, and integration tests rather than only an application template.",
      "alternatives": [
        "Classify as greenfield based only on the high-level requirement",
        "Defer classification until implementation inspection"
      ]
    },
    {
      "title": "Preserve existing API contracts where not explicitly changed",
      "rationale": "The requirement asks for safer and more reliable links, not a breaking API redesign; existing documentation and tests indicate compatibility is important.",
      "alternatives": [
        "Introduce new versioned endpoints",
        "Replace existing error and analytics response formats"
      ]
    },
    {
      "title": "Use an allowlist of web URL schemes",
      "rationale": "Allowing only HTTP and HTTPS provides an observable, enforceable baseline against executable and local-file URL schemes without requiring destination fetching.",
      "alternatives": [
        "Allow every syntactically valid URI",
        "Require HTTPS only"
      ]
    },
    {
      "title": "Reject obvious local and reserved destinations without DNS resolution",
      "rationale": "This reduces unsafe local targets while avoiding unreliable outbound DNS or HTTP validation, which could add latency, create SSRF exposure, and remain vulnerable to DNS changes.",
      "alternatives": [
        "Resolve every hostname before creation",
        "Perform an HTTP health check before creation",
        "Do not apply any reserved-destination policy"
      ]
    },
    {
      "title": "Make idempotency opt-in through Idempotency-Key",
      "rationale": "Optional idempotency improves retry safety without changing behavior for existing clients that do not send the new header.",
      "alternatives": [
        "Make idempotency mandatory",
        "Deduplicate all equivalent payloads without a client key"
      ]
    },
    {
      "title": "Enforce uniqueness in durable storage as well as application code",
      "rationale": "Application-level checks alone are insufficient under concurrency; a database constraint is the authoritative protection against redirecting to the wrong destination.",
      "alternatives": [
        "Rely only on random-code probability",
        "Use an in-memory uniqueness registry"
      ]
    },
    {
      "title": "Count only successful redirects as clicks",
      "rationale": "Analytics should represent actual resolved link visits, while unknown codes and rejected requests should remain operational failures rather than user clicks.",
      "alternatives": [
        "Count every request to the redirect endpoint",
        "Count all requests that reach the controller regardless of outcome"
      ]
    }
  ]
}

{
  "summary": "Make short-link creation and redirection safer and more reliable by using a configured public origin, rejecting canonicalized self-origin destinations, rate-limiting creation, adding configurable link expiration, and auditing/logging rate-limited and expired-link activity while preserving existing behavior.",
  "changeType": "brownfield",
  "userStories": [
    {
      "id": "US1",
      "asA": "short-link user",
      "iWant": "a created short link to use the configured public origin",
      "soThat": "the link remains correct even when requests arrive through a proxy or with an untrusted Host header",
      "acceptanceCriteria": [
        "AC1",
        "AC2"
      ]
    },
    {
      "id": "US2",
      "asA": "short-link user",
      "iWant": "URLs pointing back to this shortener to be rejected using canonical host comparison",
      "soThat": "equivalent host spellings cannot bypass the self-origin protection",
      "acceptanceCriteria": [
        "AC3",
        "AC4"
      ]
    },
    {
      "id": "US3",
      "asA": "short-link user",
      "iWant": "link creation to be rate-limited per client IP",
      "soThat": "abusive creation traffic cannot exhaust service resources",
      "acceptanceCriteria": [
        "AC5",
        "AC6",
        "AC7"
      ]
    },
    {
      "id": "US4",
      "asA": "short-link user",
      "iWant": "links to expire automatically with an optional expiration period",
      "soThat": "links do not remain usable indefinitely",
      "acceptanceCriteria": [
        "AC8",
        "AC9",
        "AC10"
      ]
    },
    {
      "id": "US5",
      "asA": "short-link visitor",
      "iWant": "expired links to return a clear HTTP status",
      "soThat": "I can distinguish an expired link from a missing link or server failure",
      "acceptanceCriteria": [
        "AC11",
        "AC12"
      ]
    },
    {
      "id": "US6",
      "asA": "service operator",
      "iWant": "rate-limited creation attempts and expired-link accesses to be logged and audited",
      "soThat": "abuse and expiration-related failures are observable and traceable",
      "acceptanceCriteria": [
        "AC13",
        "AC14"
      ]
    }
  ],
  "functional": [
    "Use the configured public origin from app.public-origin or the equivalent server configuration when constructing the shortUrl returned by the existing link-creation API.",
    "Use the configured public origin, never the incoming request Host header, for the creation response Location header.",
    "Reject a destination URL when it targets the shortener's own configured origin after canonicalizing host values for case, a trailing dot, and IDN/punycode equivalence.",
    "Rate-limit link-creation requests to 30 requests per minute per client IP. Requests over the limit must return HTTP 429 with the existing standard error response body.",
    "Apply the rate limit to creation requests only; preserve existing behavior for other endpoints.",
    "Assign a 90-day expiration by default when expiresInDays is absent from a creation request.",
    "Accept an optional expiresInDays creation field only when it is an integer from 1 through 365 inclusive.",
    "Reject invalid expiresInDays values using the existing validation/error handling convention and do not create a link.",
    "Persist the link expiration instant and evaluate it during redirect processing.",
    "Return HTTP 410 Gone with the standard error response body when a requested short code exists but has expired.",
    "Preserve existing not-found behavior for unknown short codes and existing HTTP 503 behavior when short-code generation is exhausted.",
    "Record rate-limited creation attempts and expired-link accesses in the existing audit trail, including event type, timestamp, client IP when available, and the affected endpoint or short code when applicable.",
    "Write corresponding structured application log entries for rate-limited creation attempts and expired-link accesses.",
    "Do not add malicious-URL scanning or private-network blocking as part of this change."
  ],
  "nonFunctional": [
    "The configured public origin must be the sole source for generated public short-link URLs and creation Location headers; request-controlled Host values must not influence them.",
    "Host canonicalization must consistently handle case differences, a single trailing dot, and equivalent Unicode/IDN and punycode representations.",
    "Rate-limit enforcement must be safe under concurrent requests and must not allow materially more than 30 creation requests in the configured one-minute interval for a client IP.",
    "Expiration comparisons must use a consistent server-side clock and treat a link at or beyond its expiration instant as expired.",
    "New responses must use the existing API error schema and existing global exception handling conventions.",
    "Logging and auditing must not include credentials, API keys, passwords, or full sensitive request contents.",
    "Existing analytics, redirect, creation, validation, and error behavior not explicitly changed here must remain compatible."
  ],
  "outOfScope": [
    "Malicious destination URL scanning.",
    "Blocking destinations in private or otherwise internal network ranges.",
    "Changes to analytics semantics other than recording the newly required expired-link access audit event.",
    "Changes to short-code generation or replacing the existing HTTP 503 response when code generation is exhausted.",
    "Administrative APIs for changing, extending, or revoking expiration after link creation.",
    "A distributed, cross-node rate limiter beyond the repository's existing deployment capabilities."
  ],
  "openQuestions": [
    {
      "question": "Which request metadata should be trusted when determining the client IP behind a reverse proxy?",
      "assumption": "Use the existing application/client-IP resolution convention; if none exists, use the direct remote address and do not trust forwarded headers by default.",
      "answer": ""
    },
    {
      "question": "What concrete configuration property and startup behavior should apply when the public origin is missing or malformed?",
      "assumption": "Use app.public-origin as the canonical property, support the existing server-origin configuration if already present, and fail application startup with a configuration error rather than deriving an origin from a request.",
      "answer": ""
    },
    {
      "question": "Should the rate limit use a fixed one-minute window or a rolling/sliding one-minute window?",
      "assumption": "Use a rolling/sliding one-minute window because it provides the stronger abuse-prevention interpretation of '30 requests per minute'.",
      "answer": ""
    },
    {
      "question": "Should audit records retain the client IP in plain form?",
      "assumption": "Follow the existing audit schema and retention/privacy policy; store the client IP only if the existing trail already supports it, otherwise record an available privacy-preserving identifier while retaining event observability.",
      "answer": ""
    },
    {
      "question": "What exact field name and serialization should be used for the optional expiration value?",
      "assumption": "Use the specified JSON field expiresInDays as an integer number of days.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given a valid creation request, the response shortUrl uses the configured public origin exactly as configured, including its scheme, host, and configured port where applicable."
    },
    {
      "id": "AC2",
      "criterion": "Given a valid creation request with any incoming Host header, the creation response Location header, when present, is built from the configured public origin and is unchanged when only the incoming Host header changes."
    },
    {
      "id": "AC3",
      "criterion": "A destination whose host differs from the configured public-origin host only by letter case, a trailing dot, or Unicode-versus-punycode IDN representation is rejected by the creation API."
    },
    {
      "id": "AC4",
      "criterion": "A rejected self-origin destination produces the existing invalid-URL error response and does not persist a link."
    },
    {
      "id": "AC5",
      "criterion": "For a client IP with no more than 30 creation requests in the applicable rolling 60-second interval, creation requests are processed using the existing success or validation behavior."
    },
    {
      "id": "AC6",
      "criterion": "When a client IP submits a creation request beyond 30 requests in a rolling 60-second interval, the API returns HTTP 429 and the response body conforms to the existing standard error response schema."
    },
    {
      "id": "AC7",
      "criterion": "Each rate-limited creation attempt is observable in the application logs and existing audit repository with a rate-limit event, timestamp, and client-IP or configured client identifier."
    },
    {
      "id": "AC8",
      "criterion": "A created link with no expiresInDays field has a persisted expiration instant 90 days after creation according to the service clock."
    },
    {
      "id": "AC9",
      "criterion": "A creation request with expiresInDays set to every integer from 1 through 365 is accepted and persists an expiration interval of that many days."
    },
    {
      "id": "AC10",
      "criterion": "A creation request with expiresInDays missing, non-integer, less than 1, or greater than 365 is rejected with the existing validation error response and does not persist a link."
    },
    {
      "id": "AC11",
      "criterion": "A redirect request for an existing link whose current time is at or after its expiration instant returns HTTP 410 Gone with the standard error response body and does not redirect to the destination."
    },
    {
      "id": "AC12",
      "criterion": "A redirect request for an existing link whose expiration instant has not been reached continues to return the existing redirect behavior, while a request for an unknown code continues to return the existing not-found behavior."
    },
    {
      "id": "AC13",
      "criterion": "Each expired-link access is written to the existing audit trail with an expired-link event, timestamp, and short code or equivalent link identifier."
    },
    {
      "id": "AC14",
      "criterion": "Each expired-link access produces an application log entry, and the logs and audit records for both expired accesses and rate-limited requests are queryable through the existing operational logging/audit mechanisms."
    },
    {
      "id": "AC15",
      "criterion": "When short-code generation is exhausted, the creation API still returns HTTP 503 using the existing error behavior, and the new rate-limit and expiration changes do not alter that outcome."
    }
  ],
  "decisions": [
    {
      "title": "Classify the change as brownfield",
      "rationale": "The repository contains an implemented shortener, services, repositories, controllers, documentation, and multiple tests rather than only an application template.",
      "alternatives": [
        "greenfield"
      ]
    },
    {
      "title": "Use configured public origin rather than request Host",
      "rationale": "The binding human decision explicitly requires generated public URLs and creation Location headers to be independent of request-controlled host values.",
      "alternatives": [
        "derive the origin from the incoming request Host header",
        "prefer forwarded host headers"
      ]
    },
    {
      "title": "Canonicalize IDN, case, and trailing-dot host forms before self-origin comparison",
      "rationale": "Equivalent host spellings must not bypass self-origin protection.",
      "alternatives": [
        "compare raw host strings",
        "compare only lowercase ASCII hosts"
      ]
    },
    {
      "title": "Use a rolling 60-second rate-limit window",
      "rationale": "A rolling window is the safer interpretation of 30 requests per minute and avoids boundary bursts associated with fixed windows.",
      "alternatives": [
        "fixed calendar-minute window",
        "fixed window starting with the first request"
      ]
    },
    {
      "title": "Apply rate limiting per client IP to creation only",
      "rationale": "The binding decision specifies per-client-IP link-creation throttling, while limiting other endpoints would change unrelated behavior.",
      "alternatives": [
        "rate-limit all API endpoints",
        "rate-limit per authenticated user"
      ]
    },
    {
      "title": "Default expiration to 90 days and permit 1-365 explicit days",
      "rationale": "These bounds and the default are explicitly specified by the accountable human decision and provide deterministic persistence and redirect behavior.",
      "alternatives": [
        "links never expire by default",
        "allow arbitrary expiration durations"
      ]
    },
    {
      "title": "Return 410 Gone for expired links",
      "rationale": "The binding decision explicitly distinguishes expired links from unknown links and requires HTTP 410.",
      "alternatives": [
        "return 404 Not Found",
        "redirect to an expiration page"
      ]
    },
    {
      "title": "Preserve existing error schema and code-generation behavior",
      "rationale": "The requirement explicitly requires the standard error body and existing HTTP 503 behavior, minimizing compatibility impact.",
      "alternatives": [
        "introduce a new error schema",
        "return a generic 500 for generation exhaustion"
      ]
    },
    {
      "title": "Exclude malicious-URL scanning and private-network blocking",
      "rationale": "The accountable human decision explicitly accepts those risks as out of scope for this change.",
      "alternatives": [
        "add destination reputation scanning",
        "reject private and loopback destinations"
      ]
    }
  ]
}

{
  "summary": "Improve short-link safety and reliability by using a configured public origin, canonicalising self-origin checks, limiting link creation, and adding configurable link expiration with operational auditability.",
  "changeType": "brownfield",
  "userStories": [
    {
      "id": "US1",
      "asA": "short-link creator",
      "iWant": "new short links to use the configured public origin and reject destinations that resolve to that same origin",
      "soThat": "links are not dependent on an untrusted request Host header and self-referential destinations are prevented",
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC3",
        "AC4"
      ]
    },
    {
      "id": "US2",
      "asA": "short-link creator",
      "iWant": "link creation to be rate-limited per client IP",
      "soThat": "automated or abusive creation cannot exhaust link-generation capacity for other users",
      "acceptanceCriteria": [
        "AC5",
        "AC6",
        "AC7"
      ]
    },
    {
      "id": "US3",
      "asA": "short-link creator",
      "iWant": "links to expire after a defined period with an optional creation-time override",
      "soThat": "links do not remain usable indefinitely",
      "acceptanceCriteria": [
        "AC8",
        "AC9",
        "AC10"
      ]
    },
    {
      "id": "US4",
      "asA": "short-link visitor",
      "iWant": "expired links to return a clear Gone response and valid links to redirect normally",
      "soThat": "I can distinguish an intentionally expired link from a missing link and continue using valid links",
      "acceptanceCriteria": [
        "AC11",
        "AC12",
        "AC13"
      ]
    },
    {
      "id": "US5",
      "asA": "service operator",
      "iWant": "rate-limited creation attempts and expired-link accesses to be logged and audited",
      "soThat": "abuse and expiration-related failures can be investigated",
      "acceptanceCriteria": [
        "AC14",
        "AC15"
      ]
    }
  ],
  "functional": [
    "The service shall build LinkResponse.shortUrl and redirect Location headers from the configured public origin, using app.public-origin or the existing server configuration, and shall never derive them from the incoming request Host header.",
    "The configured public origin shall be validated at startup or configuration binding time; an absent or invalid origin shall fail configuration rather than causing request-time URLs to use the request Host header.",
    "The existing self-origin URL validation shall compare the destination host with the configured public-origin host after canonicalisation: case folding, removal of trailing dots, and IDN conversion to a canonical ASCII/punycode form. Existing scheme and port comparison behavior shall otherwise be preserved.",
    "Link creation shall be limited to 30 accepted creation requests per rolling one-minute window per client IP. Requests beyond the limit shall not create a link or consume a short-code-generation attempt.",
    "Requests rejected by the creation rate limiter shall return HTTP 429 and the existing standard ErrorResponse body format.",
    "The client IP used for rate limiting shall be determined by the service's configured trusted-proxy behavior; absent trusted-proxy configuration, the direct remote address shall be used and untrusted forwarding headers shall not override it.",
    "A link created without expiresInDays shall expire 90 days after creation.",
    "A creation request may provide expiresInDays as an integer from 1 through 365 inclusive. Values outside that range, non-integer values, or malformed values shall be rejected using the existing validation/error response conventions.",
    "The selected expiration time shall be persisted with the link and shall be based on the service clock so it can be evaluated consistently.",
    "Existing link-creation behavior, including the existing HTTP 503 response when short-code generation is exhausted, shall remain unchanged except where superseded by the rate limit or expiration validation requirements.",
    "A redirect request for an expired link shall return HTTP 410 Gone with the existing standard ErrorResponse body format and shall not issue a redirect Location header.",
    "A redirect request for a non-expired link shall retain existing redirect behavior and shall issue a Location header using the configured public origin only where the existing redirect contract requires a generated short URL; the destination URL itself shall remain the stored validated target.",
    "A redirect request for a missing link shall retain the existing not-found status and error response behavior.",
    "Every rate-limited creation request shall produce an audit event in the existing audit trail containing, at minimum, the event type, client IP or privacy-preserving client identifier, timestamp, and outcome, and shall produce a corresponding application log entry.",
    "Every expired-link access shall produce an audit event in the existing audit trail containing, at minimum, the short code or link identifier, timestamp, request outcome, and expiration-related event type, and shall produce a corresponding application log entry."
  ],
  "nonFunctional": [
    "Origin construction and self-origin comparison shall be deterministic and covered for case variants, trailing-dot variants, and equivalent Unicode/IDN host representations.",
    "Rate limiting shall be atomic under concurrent requests so that concurrent requests cannot materially exceed the configured limit for one client IP.",
    "Rate-limit and expiration logs shall use the existing application logging framework, shall be structured consistently with existing logs where supported, and shall not contain credentials, API keys, passwords, or unnecessary sensitive URL data.",
    "The implementation shall use configuration or environment variables for deployment-specific values and shall not hard-code secrets.",
    "The expiration and rate-limit behavior shall be observable through HTTP responses, persisted link or audit records, and application logs without requiring implementation-specific internals.",
    "The change shall preserve existing API behavior for functionality not explicitly changed by this specification."
  ],
  "outOfScope": [
    "Malicious-URL scanning, reputation checks, or content inspection.",
    "Blocking destinations in private, loopback, link-local, or other internal network ranges.",
    "Changing the existing short-code algorithm or changing the existing HTTP 503 behavior when code generation is exhausted.",
    "Adding user authentication, per-account quotas, or administrative rate-limit management APIs.",
    "Adding a new analytics model or changing existing analytics semantics.",
    "Using the incoming request Host header to construct public short URLs or redirect response URLs."
  ],
  "openQuestions": [
    {
      "question": "What exact configuration property and fallback should provide the public origin?",
      "assumption": "Use app.public-origin as the primary property and the existing server configuration as the documented fallback. Require one valid absolute origin at startup; do not fall back to the request Host header.",
      "answer": "Human decision requires the configured public origin from app.public-origin/server configuration and prohibits request Host usage."
    },
    {
      "question": "Should the 30-per-minute rate limit use a fixed window, sliding window, or token bucket?",
      "assumption": "Use an atomic rolling one-minute window per client IP. The limit is 30 creation requests in that window.",
      "answer": ""
    },
    {
      "question": "How should client IPs be determined when the service is behind a proxy?",
      "assumption": "Use the existing trusted-proxy configuration if present; otherwise use the direct remote address and ignore untrusted forwarding headers.",
      "answer": ""
    },
    {
      "question": "Should expiration be evaluated exactly at the expiration timestamp or only by calendar date?",
