      "answer": ""
    },
    {
      "question": "What retention period should apply to audit events for rate limits and expired-link accesses?",
      "assumption": "Use the existing audit repository retention and operational policies; this change does not introduce a separate retention policy.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given a valid configured public origin and a successful link creation, the HTTP response's shortUrl is based on that configured origin, regardless of the request Host header."
    },
    {
      "id": "AC2",
      "criterion": "Given a redirect request, any generated Location header uses the configured public origin and never the request Host header; a test using a different Host header observes the same configured-origin result."
    },
    {
      "id": "AC3",
      "criterion": "Given a missing or invalid public-origin configuration, application startup or configuration binding fails with an observable configuration error instead of accepting requests that construct URLs from the request Host header."
    },
    {
      "id": "AC4",
      "criterion": "Given a destination whose host is equivalent to the configured public-origin host after case folding, trailing-dot removal, or IDN/punycode canonicalisation, link creation is rejected with the existing invalid-URL error response."
    },
    {
      "id": "AC5",
      "criterion": "For one client IP, the first 30 link-creation requests within a rolling one-minute window are processed under existing creation rules, while the next request within that window returns HTTP 429 with the standard ErrorResponse body."
    },
    {
      "id": "AC6",
      "criterion": "A request rejected with HTTP 429 does not create a database link, does not consume a short-code-generation attempt, and does not return a short URL."
    },
    {
      "id": "AC7",
      "criterion": "Requests from two distinct client IPs have independent rate-limit counters, and the configured trusted-proxy behavior determines whether a forwarded address is used."
    },
    {
      "id": "AC8",
      "criterion": "A link created without expiresInDays has a persisted expiration timestamp exactly 90 days after its creation time according to the service clock."
    },
    {
      "id": "AC9",
      "criterion": "A link created with expiresInDays values 1 and 365 persists expiration timestamps corresponding to those requested durations, while values 0, 366, negative values, non-integers, and malformed values are rejected with a validation error."
    },
    {
      "id": "AC10",
      "criterion": "Existing successful creation behavior and the existing HTTP 503 response for exhausted code generation remain observable for requests that are not rejected by rate limiting or expiration validation."
    },
    {
      "id": "AC11",
      "criterion": "A redirect request at or after a link's persisted expiration timestamp returns HTTP 410 with the standard ErrorResponse body and no Location header."
    },
    {
      "id": "AC12",
      "criterion": "A redirect request before a link's expiration timestamp retains the existing successful redirect status and behavior."
    },
    {
      "id": "AC13",
      "criterion": "A redirect request for a nonexistent short code retains the existing not-found status and standard error response."
    },
    {
      "id": "AC14",
      "criterion": "Each HTTP 429 rate-limited creation request creates an observable audit record and application log entry identifying a rate-limit rejection and its timestamp and client identifier."
    },
    {
      "id": "AC15",
      "criterion": "Each HTTP 410 expired-link access creates an observable audit record and application log entry identifying the expired-link access, short code or link identifier, timestamp, and expiration-related outcome."
    }
  ],
  "decisions": [
    {
      "title": "Classify the change as brownfield",
      "rationale": "The repository contains an implemented shortener, controllers, services, repositories, documentation, and multiple integration/unit tests rather than only a template application.",
      "alternatives": [
        "greenfield"
      ]
    },
    {
      "title": "Use configured public origin for generated URLs",
      "rationale": "The request Host header is client-controlled and must not determine public link identity or redirect metadata.",
      "alternatives": [
        "Use the request Host header",
        "Use a hard-coded origin"
      ]
    },
    {
      "title": "Canonicalise hosts before self-origin comparison",
      "rationale": "Case differences, trailing dots, and Unicode/ASCII IDN representations can describe equivalent hosts and must not bypass self-origin protection.",
      "alternatives": [
        "Compare raw host strings",
        "Compare only lowercased hosts"
      ]
    },
    {
      "title": "Apply a per-client-IP creation limit of 30 requests per rolling minute",
      "rationale": "This is the binding human decision and protects code-generation capacity while preserving independent access for different clients.",
      "alternatives": [
        "No rate limit",
        "Global service-wide rate limit",
        "Per-user authenticated rate limit"
      ]
    },
    {
      "title": "Default link expiration to 90 days with a bounded override",
      "rationale": "The binding decision specifies a 90-day default and an expiresInDays range of 1 through 365.",
      "alternatives": [
        "Never expire links",
        "Require an expiration on every creation",
        "Allow an unbounded custom duration"
      ]
    },
    {
      "title": "Return HTTP 410 for expired links",
      "rationale": "410 explicitly distinguishes an intentionally expired resource from a nonexistent short code.",
      "alternatives": [
        "Return HTTP 404",
        "Redirect to an error page",
        "Continue redirecting after expiration"
      ]
    },
    {
      "title": "Exclude malicious-URL scanning and private-network blocking",
      "rationale": "The binding human decision explicitly accepts these risks as out of scope for this change.",
      "alternatives": [
        "Add URL reputation scanning",
        "Reject private or loopback destinations"
      ]
    },
    {
      "title": "Record rate-limit and expiration events in both logs and the existing audit trail",
      "rationale": "Both operational diagnosis and durable investigation are required by the binding decision.",
      "alternatives": [
        "Log only",
        "Audit only",
        "Record neither"
      ]
    },
    {
      "title": "Preserve existing behavior outside the specified changes",
      "rationale": "The requirement explicitly preserves current behavior, including HTTP 503 on code-generation exhaustion.",
      "alternatives": [
        "Redesign all error handling",
        "Change code-generation exhaustion to HTTP 429"
      ]
    }
  ]
}

