class PublicOriginPropertiesTest {
    @Test
    void normalizesTrailingSlashesAndExposesTheConfiguredOrigin() {
        PublicOriginProperties properties = new PublicOriginProperties("https://public.example/short///");

        assertThat(properties.value()).isEqualTo("https://public.example/short");
        assertThat(properties.uri().toString()).isEqualTo("https://public.example/short");
    }

    @Test
    void rejectsMissingAndUnsafeOriginsAtConstructionTime() {
        for (String value : new String[]{null, "", "   ", "public.example", "ftp://public.example",
                "https://user:password@public.example", "https://public.example/path?x=1",
                "https://public.example/path#fragment", "https://public.example:bad"}) {
            assertThatThrownBy(() -> new PublicOriginProperties(value))
                    .isInstanceOf(IllegalStateException.class);
        }
    }

    @Test
    void canonicalizesCaseTrailingDotsAndIdnForSelfOriginValidation() {
        PublicOriginProperties properties = new PublicOriginProperties("https://xn--bcher-kva.example/short");
        UrlValidator validator = new UrlValidator(properties);

        assertThatThrownBy(() -> validator.validate("HTTPS://XN--BCHER-KVA.EXAMPLE./short/Abc1234"))
                .isInstanceOf(InvalidUrlException.class);
        assertThatCode(() -> validator.validate("https://other.example/short/Abc1234"))
                .doesNotThrowAnyException();
    }
}
