{"files":[{"path":"src/test/java/com/example/shortener/SafetyAndExpirationIntegrationTest.java","content":"package com.example.shortener;

import com.example.shortener.domain.AuditEvent;
import com.example.shortener.domain.Link;
import com.example.shortener.repository.AuditEventRepository;
import com.example.shortener.repository.LinkRepository;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest(properties = "app.public-origin=https://public.example/short")
@AutoConfigureMockMvc
class SafetyAndExpirationIntegrationTest {
    private static final AtomicLong UNIQUE = new AtomicLong();

    @Autowired MockMvc mvc;
    @Autowired LinkRepository links;
    @Autowired AuditEventRepository audits;

    @Test
    void createsConfiguredOriginUrlRegardlessOfRequestHost() throws Exception {
        String destination = uniqueUrl("origin");

        String body = mvc.perform(post("/api/links")
                        .header("Host", "attacker.example")
                        .with(request -> {
                            request.setRemoteAddr("198.51.100.101");
                            return request;
                        })
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + destination + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.shortUrl").value(org.hamcrest.Matchers.startsWith("https://public.example/short/")))
                .andReturn().getResponse().getContentAsString();

        String code = codeFrom(body);
        mvc.perform(get("/api/links/" + code).header("Host", "another-attacker.example"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.shortUrl").value("https://public.example/short/" + code));

        assertThat(body).contains("https://public.example/short/" + code)
                .doesNotContain("attacker.example");
    }

    @Test
    void canonicalEquivalentSelfOriginsAreRejected() throws Exception {
        String[] destinations = {
                "HTTPS://PUBLIC.EXAMPLE/",
                "https://public.example./short/Abc1234",
                "https://public.example/short/Abc1234",
                "https://PUBLIC.EXAMPLE./short/Abc1234"
        };

        for (String destination : destinations) {
            mvc.perform(post("/api/links")
                            .with(request -> {
                                request.setRemoteAddr("198.51.100." + (110 + UNIQUE.incrementAndGet() % 20));
                                return request;
                            })
                            .contentType(MediaType.APPLICATION_JSON)
                            .content("{\"url\":\"" + destination + "\"}"))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail").value("url must be an absolute HTTP or HTTPS URL"));
        }
    }

    @Test
    void rateLimitsThirtyRequestsPerClientAndKeepsOtherClientsIndependent() throws Exception {
        String client = "198.51.100.121";
        for (int i = 0; i < 30; i++) {
            mvc.perform(post("/api/links").with(request -> {
                        request.setRemoteAddr(client);
                        return request;
                    }).contentType(MediaType.APPLICATION_JSON)
                    .content("{\"url\":\"https://example.com/rate-" + UNIQUE.incrementAndGet() + "\"}"))
                    .andExpect(status().isCreated());
        }

        long beforeLinks = links.count();
        mvc.perform(post("/api/links").with(request -> {
                    request.setRemoteAddr(client);
                    return request;
                }).contentType(MediaType.APPLICATION_JSON)
                .content("{\"url\":\"https://example.com/rate-rejected\"}"))
                .andExpect(status().isTooManyRequests())
                .andExpect(jsonPath("$.status").value(429))
                .andExpect(jsonPath("$.detail").value("Link creation rate limit exceeded"));
        assertThat(links.count()).isEqualTo(beforeLinks);

        mvc.perform(post("/api/links").with(request -> {
                    request.setRemoteAddr("198.51.100.122");
                    request.addHeader("X-Forwarded-For", client);
                    return request;
                }).contentType(MediaType.APPLICATION_JSON)
                .content("{\"url\":\"https://example.com/independent\"}"))
                .andExpect(status().isCreated());

        List<AuditEvent> rejected = audits.findAll().stream()
                .filter(a -> "RATE_LIMIT_REJECTED".equals(a.getAction())
                        && client.equals(a.getClientIp()))
                .toList();
        assertThat(rejected).isNotEmpty().allMatch(a -> "LIMIT_EXCEEDED".equals(a.getOutcome())
                && a.getEventTime() != null);
    }

    @Test
    void defaultAndRequestedExpirationDurationsArePersistedAndReturned() throws Exception {
        Instant before = Instant.now();
        String defaultCode = create(uniqueUrl("default-expiry"), null, "198.51.100.131");
        Link defaultLink = links.findByCode(defaultCode).orElseThrow();
        assertThat(defaultLink.getExpiresAt()).isEqualTo(defaultLink.getCreatedAt().plus(90, ChronoUnit.DAYS));
        assertThat(defaultLink.getCreatedAt()).isAfterOrEqualTo(before);

        String oneDay = create(uniqueUrl("one-day"), "1", "198.51.100.132");
        String maxDays = create(uniqueUrl("max-days"), "365", "198.51.100.133");
        assertThat(links.findByCode(oneDay).orElseThrow().getExpiresAt())
                .isEqualTo(links.findByCode(oneDay).orElseThrow().getCreatedAt().plus(1, ChronoUnit.DAYS));
        assertThat(links.findByCode(maxDays).orElseThrow().getExpiresAt())
                .isEqualTo(links.findByCode(maxDays).orElseThrow().getCreatedAt().plus(365, ChronoUnit.DAYS));
    }

    @Test
    void invalidExpirationValuesReturnValidationErrors() throws Exception {
        String[] values = {"0", "366", "-1", "\"abc\"", "1.5"};
        for (String value : values) {
            mvc.perform(post("/api/links").with(request -> {
                        request.setRemoteAddr("198.51.100." + (140 + UNIQUE.incrementAndGet() % 20));
                        return request;
                    }).contentType(MediaType.APPLICATION_JSON)
                    .content("{\"url\":\"https://example.com/invalid-exp-" + UNIQUE.incrementAndGet()
                            + "\",\"expiresInDays\":" + value + "}"))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail").exists());
        }
    }

    @Test
    void expiredLinksReturnGoneWithoutLocationAndCreateAnAuditRecord() throws Exception {
        String code = "EXP" + Long.toString(UNIQUE.incrementAndGet(), 36).toUpperCase().substring(0, 4);
        code = (code + "0000000").substring(0, 7);
        final String expectedCode = code;
        Link expired = new Link(expectedCode, uniqueUrl("already-expired"),
                Instant.now().minus(2, ChronoUnit.DAYS), Instant.now().minus(1, ChronoUnit.SECONDS));
        links.saveAndFlush(expired);
        long beforeAudits = audits.count();

        mvc.perform(get("/" + expectedCode).with(request -> {
                    request.setRemoteAddr("198.51.100.151");
                    return request;
                }))
                .andExpect(status().isGone())
                .andExpect(header().doesNotExist("Location"))
                .andExpect(jsonPath("$.status").value(410))
                .andExpect(jsonPath("$.detail").value("Short link has expired"));

        assertThat(audits.findAll().stream().skip(beforeAudits))
                .anyMatch(a -> "EXPIRED_LINK_ACCESS".equals(a.getAction())
                        && expectedCode.equals(a.getCode()) && "GONE".equals(a.getOutcome())
                        && a.getEventTime() != null);
    }

    @Test
    void nonExpiredLinksRedirectAndMissingLinksRemainNotFound() throws Exception {
        String destination = uniqueUrl("valid-redirect");
        String code = create(destination, "1", "198.51.100.161");
        mvc.perform(get("/" + code).header("Host", "untrusted.example"))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));

        mvc.perform(get("/MISSING"))
                .andExpect(status().isNotFound())
                .andExpect(header().doesNotExist("Location"))
                .andExpect(jsonPath("$.detail").value("Short link not found"));
    }

    private String create(String url, String days, String remote) throws Exception {
        String expiration = days == null ? "" : ",\"expiresInDays\":" + days;
        String body = mvc.perform(post("/api/links").with(request -> {
                    request.setRemoteAddr(remote);
                    return request;
                }).contentType(MediaType.APPLICATION_JSON)
                .content("{\"url\":\"" + url + "\"" + expiration + "}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return codeFrom(body);
    }

    private String codeFrom(String body) {
        return body.replaceAll(".*\\\"code\\\":\\\"([^\\\"]+)\\\".*", "$1");
    }

    private String uniqueUrl(String prefix) {
        return "https://example.com/" + prefix + "-" + UNIQUE.incrementAndGet();
    }
}
