Make the persisted expired-link code final before using it in the stream assertion, preserving the existing integration coverage for AC11 and AC15.","testCases":[{"name":"createsConfiguredOriginUrlRegardlessOfRequestHost","type":"integration","covers":["AC1","AC2"]},{"name":"canonicalEquivalentSelfOriginsAreRejected","type":"integration","covers":["AC4"]},{"name":"rejectsMissingAndUnsafeOriginsAtConstructionTime","type":"unit","covers":["AC3"]},{"name":"rateLimitsThirtyRequestsPerClientAndKeepsOtherClientsIndependent","type":"integration","covers":["AC5","AC6","AC7","AC14"]},{"name":"allowsThirtyRequestsAndRejectsTheThirtyFirstForOneIp","type":"unit","covers":["AC5","AC6"]},{"name":"admissionIsAtomicUnderConcurrentRequests","type":"unit","covers":["AC5","AC7"]},{"name":"defaultAndRequestedExpirationDurationsArePersistedAndReturned","type":"integration","covers":["AC8","AC9"]},{"name":"invalidExpirationValuesReturnValidationErrors","type":"integration","covers":["AC9"]},{"name":"retriesCollisionThenCreatesAndAudits","type":"unit","covers":["AC10"]},{"name":"rejectsExhaustedCollisions","type":"unit","covers":["AC10"]},{"name":"expiredLinksReturnGoneWithoutLocationAndCreateAnAuditRecord","type":"integration","covers":["AC11","AC15"]},{"name":"nonExpiredLinksRedirectAndMissingLinksRemainNotFound","type":"integration","covers":["AC12","AC13"]},{"name":"redirectsCountsClicksAndReturnsDetails","type":"integration","covers":["AC12"]},{"name":"unknownCodesReturnProblemDetailsWithoutLocationHeadersAndPersistAudits","type":"integration","covers":["AC13"]},{"name":"canonicalizesCaseTrailingDotsAndIdnForSelfOriginValidation","type":"unit","covers":["AC4"]},{"name":"normalizesTrailingSlashesAndExposesTheConfiguredOrigin","type":"unit","covers":["AC1","AC2"]},{"name":"mapsCodeGenerationExhaustionToServiceUnavailableWithoutInternalDetails","type":"unit","covers":["AC10"]}],"coverageGaps":[{"target":"UrlShortenerApplication.main","reason":"Launching the Spring Boot process is not appropriate for the automated test suite; application context startup is covered separately."}],"implementationDefects":[],"decisions":[{"title":"Use a final alias for the generated expired-link code","rationale":"The code variable is reassigned while constructing the deterministic test fixture, so Java does not consider it effectively final inside the audit stream lambda. A final alias fixes compilation without weakening or changing the assertion.","alternatives":["Avoid the stream lambda and use an imperative loop","Construct the code in one expression before persisting the fixture"]}]}

