{"files":[{"path":"src/test/java/com/example/shortener/RootOriginSafetyIntegrationTest.java","content":"package com.example.shortener;

import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest(properties = "app.public-origin=http://localhost:8080")
@AutoConfigureMockMvc
@DirtiesContext(classMode = DirtiesContext.ClassMode.AFTER_EACH_TEST_METHOD)
class RootOriginSafetyIntegrationTest {
    private static final AtomicLong UNIQUE = new AtomicLong();

    @Autowired
    MockMvc mvc;

    @Test
    void rejectsCanonicalEquivalentShortCodePathsWhenConfiguredOriginHasNoPathPrefix()
            throws Exception {
        String[] destinations = {
                "HTTP://LOCALHOST:8080/AbCdEf1",
                "http://localhost.:8080/AbCdEf1"
        };

        for (String destination : destinations) {
            mvc.perform(post("/api/links")
                            .with(request -> {
                                request.setRemoteAddr("198.51.100." + UNIQUE.incrementAndGet());
                                return request;
                            })
                            .contentType(MediaType.APPLICATION_JSON)
                            .content("{\"url\":\"" + destination + "\"}"))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail")
                            .value("url must be an absolute HTTP or HTTPS URL"));
        }
    }

    @Test
    void rejectsFractionalAndStringExpirationValuesAsNonIntegerInput() throws Exception {
        String[] values = {"1.5", "\"1\""};

        for (String value : values) {
            mvc.perform(post("/api/links")
                            .with(request -> {
                                request.setRemoteAddr("203.0.113." + UNIQUE.incrementAndGet());
                                return request;
                            })
                            .contentType(MediaType.APPLICATION_JSON)
                            .content("{\"url\":\"https://example.com/non-integer-"
                                    + UNIQUE.incrementAndGet() + "\",\"expiresInDays\":"
                                    + value + "}"))
                    .andExpect(status().isBadRequest())
                    .andExpect(jsonPath("$.detail").exists());
        }
    }
}
